            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] != bg:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            comps.append(comp)
    # The multicolored connected object is the stamp; isolated colored cells are targets.
    template_comp = max(comps, key=len)
    rs = [r for r, c in template_comp]
    cs = [c for r, c in template_comp]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    ar, ac = (r0 + r1) // 2, (c0 + c1) // 2
    stamp = [[grid[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
    out = [row[:] for row in grid]
    template_set = set(template_comp)
    for comp in comps:
        if comp == template_comp:
            continue
        # Each detached singleton is a location at which to place the stamp's center.
        if len(comp) != 1:
            continue
        tr, tc = comp[0]
        for i, row in enumerate(stamp):
            for j, value in enumerate(row):
                rr, cc = tr + i - (ar-r0), tc + j - (ac-c0)
                if 0 <= rr < h and 0 <= cc < w and value != bg:
